# -*- coding: utf-8 -*-
"""КОЛІР-ВІДНОШЕННЯ (рядок 3420): відлуння вікном зі згасанням (`колір_відношення`) проти твердої межі ±15° (Р2а) на пулі руки 1,
4 сцени стенда. (1) Пари акцентів (C* ≥ neutral_C, різні слоти): ДО — `колір_річ.відношення(…, "same_hue")` (0/1), ПІСЛЯ — сила 0…1;
кодування без розмиття (σ = 0) мусить дати ті самі вердикти, що `відношення`, у кожному класі тону й `value_step`. (2) Образи-пари з пулу на краю вікна
(сукня/верх × аксесуар, обидва — вимір, 8–25° кола, площі 0.6 і 0.05): K-COL-05 (`колір_хрома.відлуння`, перевірка композитора) ДО — тверде
кодування (= межа Р2а) і ПІСЛЯ — вікно; `-д` — кожен образ. Запуск із джерела/: python3 проби/колір_відношення_вікна.py [-д]"""
import json, random, sys, collections as K; sys.path.insert(0, ".")
import bridge as B, colorspace as cs, стенд_знімок as СЗ, колір_річ as КР, outfit as O, колір_хрома as КХ
try: import колір_відношення as КВ
except ImportError: КВ = None                       # ДО: база без кодування
вх0 = json.load(open("стенд_вх.json", encoding="utf-8")); Л, П, Д = K.Counter(), [], []
def тверде(f):                                      # кодування без розмиття = межі колір_річ (Р2а, K-PAL-05, RELATIONS)
    б = (КВ.СІГМА_МЕЖІ, КВ.СІГМА_СВІТЛОТИ); КВ.СІГМА_МЕЖІ = КВ.СІГМА_СВІТЛОТИ = 0.0; т = (КВ.ХРОМА_ТОНУ, КВ.СВІТЛОТА_ТОНУ); КВ.ХРОМА_ТОНУ = КВ.СВІТЛОТА_ТОНУ = -1e9
    try: return f()
    finally: (КВ.СІГМА_МЕЖІ, КВ.СІГМА_СВІТЛОТИ), (КВ.ХРОМА_ТОНУ, КВ.СВІТЛОТА_ТОНУ) = б, т
for назва in ("офіс·18°C", "дощ·ресторан·вечір", "весілля·гість", "спека·парк"):
    сц = dict(СЗ.СЦЕНАРІЇ[назва]); к = json.loads(B.виклик("запити", json.dumps(dict(вх0, сценарій=сц, випадок=назва), ensure_ascii=False)))["кандидати"]
    кат = B.каталог_останнього_пакета(); зі = {r["id"]: r for r in кат}; рп = random.Random(3)
    ак = [(с, зі[r["id"]]) for с, рр in к.items() for r in рр if зі.get(r["id"]) and (КР.межі_кольору(зі[r["id"]]) or (0, 0, 0))[2] >= 12]
    for i, (с1, a) in enumerate(ак):
        for с2, b in ак[i + 1:]:
            if с1 == с2 or КВ is None: continue
            до = КР.відношення(a, b, "same_hue"); с = КВ.сила(a, b, "same_hue", певність=False); в = КВ.вердикт(с)
            Л["тверде кодування ≠ відношення (класи тону, value_step)"] += any(тверде(lambda: КВ.вердикт(КВ.сила(a, b, кл, певність=False))) != КР.відношення(a, b, кл) for кл in list(КВ.ВІКНА_ТОНУ)[:3] + ["triadic", "split", "complementary", "value_step"])
            Л["пари: ДО %s → ПІСЛЯ %s" % (до, в)] += 1; Л["пари: ДО так, сила < 0.95"] += до == "так" and с[0] < 0.95; Л["пари: ДО ні, сила > 0.05"] += до == "ні" and с[1] > 0.05
            if 0.2 < с[0] == с[1] < 0.8 and рп.random() < 0.02: П.append("  %-34s %s × %-34s %s Δколо %5.1f → сила %.2f" % ((a.get("назва") or "")[:34], cs.hex_з_lab(a["lab"]), (b.get("назва") or "")[:34], cs.hex_з_lab(b["lab"]), КР.кут_на_колі(cs.lch(a["lab"])[2], cs.lch(b["lab"])[2]), с[0]))
    for с1, a in ак:                                # (2) образ-пара на краю вікна: верх/сукня (площа 0.6) + аксесуар (0.05), обидва — вимір
        for с2, b in ак:
            if КВ is None or с1 not in ("сукня", "верх") or с2 not in ("сумка", "взуття", "шарф", "сережки", "намисто") or КР.не_вимір(a) or КР.не_вимір(b): continue
            if not 8 <= КР.кут_на_колі(cs.lch(a["lab"])[2], cs.lch(b["lab"])[2]) <= 25: continue
            E = O.елементи([dict(x, слот=с, площа=п, hex=cs.hex_з_lab(x["lab"])) for x, с, п in ((a, с1, 0.6), (b, с2, 0.05))])
            до, піс = (sorted((z["сила"], z.get("сила_нп")) for z in f() if z.get("правило") == "K-COL-05") for f in (lambda: тверде(lambda: КХ.відлуння(E)), lambda: КХ.відлуння(E)))
            Л["образи-пари на краю: усього"] += 1; Л["  сирота ДО"] += len(до); Л["  сирота ПІСЛЯ"] += len(піс); Л["  вердикт змінено (є / нема сироти)"] += len(до) != len(піс)
            Л["  сила сироти змінена"] += len(до) == len(піс) and до != піс; Л["  сума сили ДО ×100"] += round(100 * sum(x[1] or 0 for x in до)); Л["  сума сили ПІСЛЯ ×100"] += round(100 * sum(x[1] or 0 for x in піс))
            Д.append("%s %-30s %s × %-30s %s Δколо %4.1f сила %.2f · ДО %s → ПІСЛЯ %s" % (назва[:6], (a.get("назва") or "")[:30], cs.hex_з_lab(a["lab"]), (b.get("назва") or "")[:30], cs.hex_з_lab(b["lab"]), КР.кут_на_колі(cs.lch(a["lab"])[2], cs.lch(b["lab"])[2]), КВ.сила(a, b, "same_hue", певність=False)[0], до or "—", піс or "—"))
for к_, v in sorted(Л.items()): print("  %-52s %6d" % (к_, v))
print("приклади на краю вікна (сила 0.2–0.8):\n" + "\n".join(П[:8]))
if "-д" in sys.argv: print("\n".join(Д))
